// loadLocalToolTime derives a session-level ToolProfile from the live
// transcript by dispatching to the agent-specific ToolCallWalker.
// Runs for every session with a transcript (active or ended) so offline
// or pre-enrichment sessions get a baseline; server enrichment, when
// later rolled up from checkpoints, supersedes this via
// rollupServerToolProfiles.
func loadLocalToolTime(ctx context.Context, s *ActivitySession, agentType types.AgentType, transcriptPath string) {
	if transcriptPath == "" {
		return
	}
	profile, err := DeriveToolTime(agentType, transcriptPath)
	if err != nil {
		logging.Debug(ctx, "activity: DeriveToolTime failed; skipping local tool-time",
			"session", s.SessionID, "error", err.Error())
		return
	}
	if profile == nil || profile.Total == 0 {
		return
	}
	s.ToolProfile = profile
}

