// SpanMinutes returns the honest first-to-last checkpoint timestamp span
// in minutes. Returns 0 when fewer than two checkpoints exist.
func (a ActivitySession) SpanMinutes() float64 {
	if len(a.Checkpoints) < 2 {
		return 0
	}
	first := a.Checkpoints[0].CreatedAt
	last := a.Checkpoints[0].CreatedAt
	for _, cp := range a.Checkpoints[1:] {
		if cp.CreatedAt.Before(first) {
			first = cp.CreatedAt
		}
		if cp.CreatedAt.After(last) {
			last = cp.CreatedAt
		}
	}
	return last.Sub(first).Minutes()
}

// ActivityCheckpoint is a projection of one committed checkpoint.
//
//nolint:revive // ActivityCheckpoint is clearer than Checkpoint in the activity package context
type ActivityCheckpoint struct {
	Repo         string
	SessionID    string
	ID           id.CheckpointID
	CreatedAt    time.Time
	IsTask       bool
	ToolUseID    string
	Agent        string
	Model        string
	FilesTouched []string
	FocusAreas   []string
	LinkedCommit string
	TokenUsage   *agent.TokenUsage
	TurnID       string
	Labels       []string // tier 3
	ToolProfile  *ToolProfile
	Badges       []string
	Source       DataSource
}

// ToolProfile mirrors api/src/types.ts ToolProfile but with optional
// per-category durations. DurationMs is 0 when the server hasn't
// provided it yet.
type ToolProfile struct {
	Categories map[string]ToolCategoryMetrics `json:"categories"`
	Total      int                            `json:"total"`
}

// ToolCategoryMetrics holds count and optional duration for a tool category.
type ToolCategoryMetrics struct {
	Count      int   `json:"count"`
	DurationMs int64 `json:"durationMs,omitempty"`
}

// ActivityDay is a per-day rollup shown in range/history/heatmap views.
//
//nolint:revive // ActivityDay is clearer than Day in the activity package context
type ActivityDay struct {
	Date            time.Time
	Repos           []string
	Sessions        int
	Checkpoints     int
	TaskCheckpoints int
	LinkedCommits   int
	TokenTotal      int
	LabelCounts     map[string]int
	FocusAreaCounts map[string]int
	ResumeCount     int
	ToolTimeMs      map[string]int64 // per-category duration
}

// ActivityRangeSummary aggregates across a time range.
//
//nolint:revive // ActivityRangeSummary is clearer than RangeSummary in the activity package context
type ActivityRangeSummary struct {
	From            time.Time
	To              time.Time
	ReposTouched    []string
	Sessions        int
	Checkpoints     int
	TaskCheckpoints int
	LinkedCommits   int
	ActiveDays      int
	TokenTotal      int
	LabelCounts     map[string]int
	FocusAreaCounts map[string]int
	AgentCounts     map[string]int
	ModelCounts     map[string]int
	RepoSummaries   []ActivityRepoSummary
	AgentSummaries  []ActivityAgentSummary
	TopSessions     []ActivitySession
	ToolTimeMs      map[string]int64
}

// ActivityRepoSummary is per-repo rollup for the `repos` tab.
//
//nolint:revive // ActivityRepoSummary is clearer than RepoSummary in the activity package context
type ActivityRepoSummary struct {
	Repo          string
	Sessions      int
	Checkpoints   int
	LinkedCommits int
	LinkedRate    float64 // 0.0 - 1.0
	FocusAreas    []string
	LabelCounts   map[string]int
	AgentsUsed    []string
	TopSessions   []ActivitySession
